From 7b127e274b500e5784467be0169dd6c1d6ec5e65 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:26:01 +0100
Subject: [PATCH] sendfile: wait for the running transfer to a device before
 sending more

Sending a file to a device that was still receiving another one failed
with "OBEX Connect failed", since it refuses a second session. Now when
the device refuses while a file is sent to it, the send waits its turn.

BUG: 362146
---
 src/sendfile/pages/connectingpage.cpp | 37 ++++++++++++++++++++++++++-
 src/sendfile/pages/connectingpage.h   |  4 +++
 2 files changed, 40 insertions(+), 1 deletion(-)

diff --git a/src/sendfile/pages/connectingpage.cpp b/src/sendfile/pages/connectingpage.cpp
index dc01397d..9550c186 100644
--- a/src/sendfile/pages/connectingpage.cpp
+++ b/src/sendfile/pages/connectingpage.cpp
@@ -13,11 +13,15 @@

 #include <QDBusObjectPath>

+#include <algorithm>
+
 #include <KLocalizedString>

 #include <BluezQt/Device>
 #include <BluezQt/InitObexManagerJob>
+#include <BluezQt/ObexSession>
 #include <BluezQt/PendingCall>
+#include <BluezQt/Services>

 ConnectingPage::ConnectingPage(SendFileWizard *wizard)
     : QWizardPage(wizard)
@@ -54,15 +58,37 @@ void ConnectingPage::initJobResult(BluezQt::InitObexManagerJob *job)
         return;
     }

+    m_manager = job->manager();
+    connect(m_manager, &BluezQt::ObexManager::sessionRemoved, this, [this] {
+        if (m_waiting) {
+            createSession();
+        }
+    });
+
+    createSession();
+}
+
+void ConnectingPage::createSession()
+{
+    m_waiting = false;
+    connLabel->setText(i18nc("Connecting to a Bluetooth device", "Connecting to %1…", m_device->name()));
+
     // Create ObjectPush session
     QVariantMap map;
     map[QStringLiteral("Target")] = QStringLiteral("opp");
-    BluezQt::PendingCall *call = job->manager()->createSession(m_device->address(), map);
+    BluezQt::PendingCall *call = m_manager->createSession(m_device->address(), map);
     connect(call, &BluezQt::PendingCall::finished, this, &ConnectingPage::createSessionFinished);
 }

 void ConnectingPage::createSessionFinished(BluezQt::PendingCall *call)
 {
+    // The device refuses a second connection while another file is being sent to it, so wait for that to finish
+    if (call->error() && isSendingToDevice()) {
+        m_waiting = true;
+        connLabel->setText(i18nc("Waiting for a Bluetooth device", "Waiting for the current transfer to %1 to finish…", m_device->name()));
+        return;
+    }
+
     if (call->error()) {
         qCWarning(BLUEDEVIL_SENDFILE_LOG) << "Error creating session" << call->errorText();
         m_wizard->setErrorMessage(call->errorText());
@@ -73,6 +99,15 @@ void ConnectingPage::createSessionFinished(BluezQt::PendingCall *call)
     m_wizard->startTransfer(call->value().value<QDBusObjectPath>());
 }

+bool ConnectingPage::isSendingToDevice() const
+{
+    const auto sessions = m_manager->sessions();
+    return std::any_of(sessions.cbegin(), sessions.cend(), [this](const BluezQt::ObexSessionPtr &session) {
+        return session->destination().compare(m_device->address(), Qt::CaseInsensitive) == 0
+            && session->target().compare(BluezQt::Services::ObexObjectPush, Qt::CaseInsensitive) == 0;
+    });
+}
+
 QList<QWizard::WizardButton> ConnectingPage::wizardButtonsLayout() const
 {
     QList<QWizard::WizardButton> list;
diff --git a/src/sendfile/pages/connectingpage.h b/src/sendfile/pages/connectingpage.h
index eac57884..79690965 100644
--- a/src/sendfile/pages/connectingpage.h
+++ b/src/sendfile/pages/connectingpage.h
@@ -30,10 +30,14 @@ public:
 private Q_SLOTS:
     void initJobResult(BluezQt::InitObexManagerJob *job);
     void createSessionFinished(BluezQt::PendingCall *call);
+    void createSession();

 private:
     QList<QWizard::WizardButton> wizardButtonsLayout() const;
+    bool isSendingToDevice() const;

     SendFileWizard *const m_wizard;
     BluezQt::DevicePtr m_device;
+    BluezQt::ObexManager *m_manager = nullptr;
+    bool m_waiting = false;
 };
